1	go	{"topic": "go", "questions": [{"id": 1, "code": "x := \\"hello\\"", "hint": "Текст в кавычках в Go — это тип string.", "text": "Какой тип у переменной x?", "correct": 2, "options": ["int", "float64", "string", "bool"]}, {"id": 2, "code": "fmt.Println(2 * 2 * 2)", "hint": "2*2*2 = 8. В Go для простых чисел нет оператора степени.", "text": "Что выведет код?", "correct": 1, "options": ["6", "8", "4", "23"]}, {"id": 3, "code": "fmt.Println(10 % 3)", "hint": "% — остаток от деления. 10 разделить на 3 будет 3, остаток 1.", "text": "Результат операции?", "correct": 1, "options": ["3", "1", "0", "10"]}, {"id": 4, "code": "a := []int{10, 20, 30}\\nfmt.Println(a[0])", "hint": "Индексация в срезах начинается с 0. Первый элемент — 10.", "text": "Что выведет код?", "correct": 2, "options": ["20", "30", "10", "Ошибка"]}, {"id": 5, "code": "func main() { }", "hint": "Если функция ничего не возвращает, тип возвращаемого значения просто не указывается.", "text": "Как в Go объявляется функция, которая ничего не возвращает?", "correct": 2, "options": ["void main()", "func main() int", "func main()", "main() func"]}, {"id": 6, "code": "x := 5\\nfmt.Println(x + 2)", "hint": "Обычное сложение целых чисел.", "text": "Какой результат будет выведен?", "correct": 1, "options": ["52", "7", "10", "Ошибка"]}, {"id": 7, "code": "", "hint": "Тип int используется для работы с целыми числами.", "text": "Какой базовый тип данных используется для целых чисел?", "correct": 2, "options": ["bool", "string", "int", "float64"]}, {"id": 8, "code": "a := true\\nfmt.Println(a)", "hint": "Логический тип bool выводит true или false.", "text": "Что выведет программа?", "correct": 0, "options": ["true", "false", "1", "Ошибка"]}, {"id": 9, "code": "x := 3\\nx++", "hint": "++ увеличивает значение переменной на единицу.", "text": "Что делает оператор ++?", "correct": 1, "options": ["Уменьшает число", "Увеличивает на 1", "Умножает на 2", "Обнуляет"]}, {"id": 10, "code": "fmt.Println(15 / 2)", "hint": "Деление int на int в Go отбрасывает дробную часть и даёт целое число.", "text": "Что выведет код?", "correct": 0, "options": ["7", "7.5", "8", "Ошибка"]}, {"id": 11, "code": "", "hint": "В Go есть только один цикл — это цикл for.", "text": "Какой ключевой цикл используется в Go для любых повторений?", "correct": 1, "options": ["while", "for", "switch", "foreach"]}, {"id": 12, "code": "for i := 0; i < 3; i++ {\\n    fmt.Print(i)\\n}", "hint": "Цикл начинается с i = 0 и работает, пока i меньше 3.", "text": "Что выведет код?", "correct": 1, "options": ["123", "012", "321", "Ошибка"]}, {"id": 13, "code": "", "hint": "Конструкция if проверяет логическое условие.", "text": "Какой оператор используется для проверки условий?", "correct": 1, "options": ["for", "if", "func", "return"]}, {"id": 14, "code": "x := 10\\nif x > 5 {\\n    fmt.Println(\\"Yes\\")\\n}", "hint": "Условие 10 > 5 верно, поэтому выполнится вывод 'Yes'.", "text": "Что выведет код?", "correct": 1, "options": ["No", "Yes", "10", "Ошибка"]}, {"id": 15, "code": "", "hint": "// используется для комментариев до конца строки.", "text": "Как обозначается однострочный комментарий в Go?", "correct": 1, "options": ["", "//", "/* */", "#"]}, {"id": 16, "code": "", "hint": "Println выводит аргументы и автоматически добавляет переход на новую строку.", "text": "Какая функция стандартного пакета fmt используется для вывода текста с новой строки?", "correct": 1, "options": ["fmt.Scanln()", "fmt.Println()", "fmt.Print()", "fmt.Printf()"]}, {"id": 17, "code": "name := \\"Tom\\"\\nfmt.Println(\\"Hi \\" + name)", "hint": "Оператор + соединяет (конкатенирует) две строки.", "text": "Что выведет код?", "correct": 2, "options": ["Hi", "Tom", "Hi Tom", "Ошибка"]}, {"id": 18, "code": "x := 5", "hint": "В Go точки с запятой разделяются компилятором автоматически на концах строк.", "text": "Нужно ли обязательно ставить точку с запятой (;) в конце каждой инструкции в Go?", "correct": 1, "options": ["Да, всегда", "Нет, компилятор расставляет их автоматически", "Только в цикле for", "Только внутри функций"]}, {"id": 19, "code": "", "hint": "Срезы (slices) — это гибкие и динамичные обертки над массивами, используемые чаще всего.", "text": "Как в Go называется динамический список (аналог массива изменяемой длины)?", "correct": 1, "options": ["Массив (Array)", "Срез (Slice)", "Структура (Struct)", "Карта (Map)"]}, {"id": 20, "code": "nums := []int{1, 2, 3}\\nfmt.Println(len(nums))", "hint": "Встроенная функция len() возвращает количество элементов.", "text": "Какая функция используется для получения длины среза или строки?", "correct": 2, "options": ["nums.Length", "size(nums)", "len(nums)", "count(nums)"]}, {"id": 21, "code": "x := 4\\nfmt.Println(x * 5)", "hint": "Умножение: 4 * 5 = 20.", "text": "Что выведет код?", "correct": 1, "options": ["9", "20", "45", "Ошибка"]}, {"id": 22, "code": "", "hint": "float64 — стандартный тип для дробных чисел по умолчанию.", "text": "Какой тип данных чаще всего используется для чисел с плавающей точкой (дробных)?", "correct": 2, "options": ["int", "bool", "float64", "string"]}, {"id": 23, "code": "x := 2.5\\nfmt.Println(x)", "hint": "Переменная x автоматически получает тип float64 и выводится как дробь.", "text": "Что выведет код?", "correct": 2, "options": ["2", "25", "2.5", "Ошибка"]}, {"id": 24, "code": "", "hint": "Оператор != проверяет значения на неравенство.", "text": "Какой оператор означает 'не равно'?", "correct": 1, "options": ["=", "!=", "==", "<>"]}, {"id": 25, "code": "", "hint": "break полностью прерывает выполнение текущего цикла.", "text": "Что делает ключевое слово break?", "correct": 1, "options": ["Продолжает цикл", "Немедленно завершает цикл", "Создает переменную", "Вызывает функцию"]}, {"id": 26, "code": "x := 7\\nfmt.Println(x % 2)", "hint": "Остаток от деления 7 на 2 равен 1.", "text": "Что выведет код?", "correct": 1, "options": ["0", "1", "2", "7"]}, {"id": 27, "code": "", "hint": "Пакет fmt (format) отвечает за форматированный ввод и вывод.", "text": "Из какого пакета импортируются стандартные функции вывода Println и Printf?", "correct": 1, "options": ["main", "fmt", "io", "os"]}, {"id": 28, "code": "c := 'A'", "hint": "Символы в одинарных кавычках в Go называются рунами (rune) и представляют собой кодовые точки Unicode.", "text": "Какой тип данных представляет собой одиночный символ (руну) в Go?", "correct": 0, "options": ["rune", "string", "bool", "byte"]}, {"id": 29, "code": "", "hint": "Конструкция for без условий создает бесконечный цикл.", "text": "Как написать бесконечный цикл в Go?", "correct": 2, "options": ["while true { }", "for true { }", "for { }", "loop { }"]}, {"id": 30, "code": "x := 1\\nfor x < 4 {\\n    fmt.Print(x)\\n    x++\\n}", "hint": "Цикл for может работать как while. x последовательно равен 1, 2, 3.", "text": "Что выведет код?", "correct": 0, "options": ["123", "0123", "234", "Ошибка"]}, {"id": 31, "code": "", "hint": "continue завершает текущий шаг и переходит к следующей итерации цикла.", "text": "Что делает ключевое слово continue?", "correct": 1, "options": ["Завершает программу", "Пропускает остаток текущей итерации цикла", "Удаляет цикл", "Создает функцию"]}, {"id": 32, "code": "fmt.Println(5 == 5)", "hint": "Оператор == сравнивает значения. 5 равно 5, результат — true.", "text": "Что выведет код?", "correct": 0, "options": ["true", "false", "5", "Ошибка"]}, {"id": 33, "code": "", "hint": "Функция main() внутри пакета main является точкой входа.", "text": "Какое имя должна иметь главная функция для запуска программы на Go?", "correct": 1, "options": ["start()", "main()", "run()", "init()"]}, {"id": 34, "code": "package main", "hint": "Любая запускаемая программа должна начинаться с package main.", "text": "Какое имя должен иметь главный пакет в Go, чтобы программа компилировалась в исполняемый файл?", "correct": 2, "options": ["package go", "package root", "package main", "package global"]}, {"id": 35, "code": "", "hint": "&& возвращает true только если оба условия верны.", "text": "Какой оператор используется для логического И (AND)?", "correct": 1, "options": ["||", "&&", "!", "&"]}, {"id": 36, "code": "fmt.Println(true && false)", "hint": "Истина И Ложь дает Ложь (false).", "text": "Что выведет код?", "correct": 1, "options": ["true", "false", "1", "Ошибка"]}, {"id": 37, "code": "", "hint": "В Go нет классов. Данные объединяются с помощью ключевого слова struct.", "text": "Что используется в Go вместо классов для создания собственных сложных типов данных?", "correct": 1, "options": ["Классы", "Структуры (struct)", "Интерфейсы", "Списки"]}, {"id": 38, "code": "x := 9\\nfmt.Println(x / 3)", "hint": "9 разделить на 3 будет 3.", "text": "Что выведет код?", "correct": 0, "options": ["3", "6", "9", "0"]}, {"id": 39, "code": "", "hint": "Оператор := используется для краткого объявления и инициализации переменной внутри функций.", "text": "Как правильно объявить переменную `age` со значением 20 с помощью краткой формы?", "correct": 0, "options": ["age := 20", "int age = 20", "age = 20", "var age = 20"]}, {"id": 40, "code": "", "hint": "return прекращает выполнение функции и возвращает значение, если оно есть.", "text": "Что делает оператор return?", "correct": 1, "options": ["Повторяет цикл", "Возвращает результат из функции", "Создает структуру", "Удаляет переменную"]}, {"id": 41, "code": "fmt.Println(3 > 1)", "hint": "3 действительно больше 1, поэтому результат true.", "text": "What will be printed?", "correct": 0, "options": ["true", "false", "3", "1"]}, {"id": 42, "code": "", "hint": "bool (boolean) — логический тип данных.", "text": "Какой тип данных принимает значения true или false?", "correct": 2, "options": ["int", "string", "bool", "float64"]}, {"id": 43, "code": "a := \\"Hi\\"\\nb := \\"!\\"\\nfmt.Println(a + b)", "hint": "Строки складываются встык без автоматических пробелов.", "text": "Что выведет код?", "correct": 0, "options": ["Hi!", "Hi !", "!", "Ошибка"]}, {"id": 44, "code": "", "hint": "Одиночное `=` — это присваивание (или часть `:=`), а двойное `==` — сравнение.", "text": "Что означает оператор == ?", "correct": 1, "options": ["Присваивание", "Сравнение на равенство", "Умножение", "Деление"]}, {"id": 45, "code": "x := 0\\nif x == 0 {\\n    fmt.Println(\\"Zero\\")\\n}", "hint": "Поскольку x равен 0, условие выполняется и выводится 'Zero'.", "text": "Что выведет код?", "correct": 1, "options": ["0", "Zero", "false", "Ошибка"]}, {"id": 46, "code": "", "hint": "|| возвращает true, если хотя бы одно из условий верно.", "text": "Какой оператор означает логическое ИЛИ (OR)?", "correct": 1, "options": ["&&", "||", "!", "%"]}, {"id": 47, "code": "fmt.Println(false || true)", "hint": "Ложь ИЛИ Истина дает Истину (true).", "text": "Что выведет код?", "correct": 0, "options": ["true", "false", "0", "Ошибка"]}, {"id": 48, "code": "", "hint": "Стандартные интерпретируемые строки создаются в двойных кавычках.", "text": "С помощью каких кавычек создаются обычные строки (string) в Go?", "correct": 2, "options": ["Одинарные кавычки ''", "Обратные апострофы ``", "Двойные кавычки \\"\\"", "Угловые кавычки <>"]}, {"id": 49, "code": "a := []int{5, 6, 7}\\nfmt.Println(a[2])", "hint": "Индекс 0 — это 5, индекс 1 — это 6, индекс 2 — это 7.", "text": "Что выведет код?", "correct": 2, "options": ["5", "6", "7", "Ошибка"]}, {"id": 50, "code": "", "hint": "Ключевое слово var используется для стандартного объявления переменных.", "text": "Какой ключевой символ используется для классического объявления переменной (без краткой формы)?", "correct": 1, "options": ["let", "var", "int", "make"]}, {"id": 51, "code": "x := 10\\nx = 20\\nfmt.Println(x)", "hint": "Значение переменной можно изменять обычным оператором присваивания `=`.", "text": "Что выведет код?", "correct": 1, "options": ["10", "20", "Ошибка компиляции", "x"]}, {"id": 52, "code": "", "hint": "Конструкция `var s []int` создает срез со значением по умолчанию (nil).", "text": "Как объявить пустой срез (slice) целых чисел?", "correct": 0, "options": ["var s []int", "s := int[]", "var s slice", "s = new(int)"]}, {"id": 53, "code": "var x int\\nfmt.Println(x)", "hint": "В Go числовые типы по умолчанию инициализируются нулем.", "text": "Какое значение по умолчанию имеет переменная типа int?", "correct": 1, "options": ["nil", "0", "1", "Ошибка"]}, {"id": 54, "code": "var s string", "hint": "Строки по умолчанию инициализируются пустой строкой `\\"\\"`.", "text": "Какое значение по умолчанию имеет переменная типа string?", "correct": 0, "options": ["\\"\\"", "nil", "null", "space"]}, {"id": 55, "code": "var b bool", "hint": "Значение по умолчанию для bool — это false.", "text": "Какое значение по умолчанию имеет логический тип bool?", "correct": 1, "options": ["true", "false", "nil", "0"]}, {"id": 56, "code": "a := []int{1}\\na = append(a, 2)", "hint": "append() добавляет один или несколько элементов в конец существующего среза.", "text": "Что делает функция append()?", "correct": 1, "options": ["Удаляет элемент", "Добавляет элемент в конец среза", "Считает длину", "Очищает срез"]}, {"id": 57, "code": "package main\\nimport \\"fmt\\"\\nfunc main() {\\n    x := 5\\n    fmt.Println(\\"Hello\\")\\n}", "hint": "Компилятор Go строго запрещает оставлять неиспользуемые локальные переменные.", "text": "Что произойдет при попытке скомпилировать этот код?", "correct": 1, "options": ["Выведет Hello", "Ошибка: переменная x объявлена, но не используется", "Выведет Hello и 5", "Ошибка: нет точки с запятой"]}, {"id": 58, "code": "import (\\n    \\"fmt\\"\\n    \\"math\\"\\n)", "hint": "Неиспользуемые импорты в Go считаются ошибкой компиляции.", "text": "Что произойдет, если импортировать пакет, но не использовать его?", "correct": 2, "options": ["Программа скомпилируется", "Пакет удалится сам", "Ошибка компиляции", "Предупреждение в консоли"]}, {"id": 59, "code": "", "hint": "Тип map используется для хранения неупорядоченных пар ключ-значение.", "text": "Как в Go называется коллекция пар 'ключ-значение' (хеш-таблица)?", "correct": 2, "options": ["Array", "Slice", "Map (Карта)", "Struct"]}, {"id": 60, "code": "m := make(map[string]int)", "hint": "Функция make() выделяет и инициализирует память для срезов, карт и каналов.", "text": "Какая встроенная функция используется для создания карт (map) или каналов?", "correct": 2, "options": ["new()", "create()", "make()", "alloc()"]}, {"id": 61, "code": "fmt.Printf(\\"%d\\", 10)", "hint": "Спецификатор `%d` в Printf форматирует число в десятичную систему.", "text": "Что выведет код?", "correct": 1, "options": ["%d", "10", "десять", "Ошибка"]}, {"id": 62, "code": "fmt.Printf(\\"Hello %...\\", \\"World\\")", "hint": "Для вставки строк в Printf используется символ `%s` (string).", "text": "Какой спецификатор (глагол) в fmt.Printf используется для вывода строки?", "correct": 2, "options": ["%d", "%f", "%s", "%t"]}, {"id": 63, "code": "", "hint": "`%v` (value) выводит значение в стандартном формате.", "text": "Какой спецификатор в fmt.Printf автоматически подбирает удобный формат для любого значения?", "correct": 1, "options": ["%s", "%v", "%d", "%x"]}, {"id": 64, "code": "type Person struct { Age int }\\nvar p Person", "hint": "Доступ к полям структуры осуществляется через точку.", "text": "Как правильно обратиться к полю `Age` у структуры `p`?", "correct": 1, "options": ["p->Age", "p.Age", "p[Age]", "p(Age)"]}, {"id": 65, "code": "x := 5\\nif x < 10 {\\n    fmt.Print(\\"A\\")\\n} else {\\n    fmt.Print(\\"B\\")\\n}", "hint": "Условие 5 < 10 верно, выполнится только блок if.", "text": "Что выведет этот код?", "correct": 0, "options": ["A", "B", "AB", "Ошибка"]}, {"id": 66, "code": "", "hint": "Конструкция switch используется для удобного ветвления по разным значениям.", "text": "Какое ключевое слово заменяет множественные условия if-else?", "correct": 1, "options": ["for", "switch", "select", "goto"]}, {"id": 67, "code": "switch x {\\ncase 1: fmt.Print(\\"1\\")\\ncase 2: fmt.Print(\\"2\\")\\n}", "hint": "В Go выполнение не переходит на следующий case автоматически, поэтому break ставить не нужно.", "text": "Нужно ли писать break в конце каждого кейса в switch в Go?", "correct": 1, "options": ["Да, обязательно", "Нет, он срабатывает автоматически", "Только если это числа", "Только в блоке default"]}, {"id": 68, "code": "", "hint": "Оператор `fallthrough` передает управление следующей ветке case.", "text": "Какое ключевое слово используется в switch, чтобы принудительно перейти к следующему кейсу?", "correct": 2, "options": ["continue", "break", "fallthrough", "next"]}, {"id": 69, "code": "x := 5", "hint": "Оператор `&` (амперсанд) возвращает указатель на переменную (ее адрес).", "text": "Как получить адрес переменной в памяти (создать указатель)?", "correct": 0, "options": ["&x", "*x", "new(x)", "ptr(x)"]}, {"id": 70, "code": "p := &x\\nfmt.Println(*p)", "hint": "Оператор `*` позволяет получить доступ к значению, на которое ссылается указатель.", "text": "Что делает оператор * перед указателем?", "correct": 1, "options": ["Умножает адрес", "Разыменовывает (получает значение по адресу)", "Удаляет переменную", "Создает новый адрес"]}, {"id": 71, "code": "", "hint": "`nil` в Go — это аналог null в других языках, означающий отсутствие значения.", "text": "Какое значение имеют неинициализированные указатели, срезы и карты?", "correct": 2, "options": ["0", "void", "nil", "false"]}, {"id": 72, "code": "a := 5\\nb := &a\\n*b = 10\\nfmt.Println(a)", "hint": "Изменение значения через разыменованный указатель `*b` меняет саму переменную `a`.", "text": "Что выведет данный код?", "correct": 1, "options": ["5", "10", "Адрес памяти", "Ошибка"]}, {"id": 73, "code": "s := \\"Go\\"", "hint": "Функция len() работает как со срезами, так и со строками.", "text": "Как узнать количество символов (байт) в строке?", "correct": 2, "options": ["s.Length()", "count(s)", "len(s)", "size(s)"]}, {"id": 74, "code": "s := []int{10, 20, 30, 40}\\nfmt.Println(s[1:3])", "hint": "Срез s[1:3] берет элементы с индекса 1 включительно по индекс 3 исключительно.", "text": "Что выведет код?", "correct": 1, "options": ["[10, 20]", "[20, 30]", "[20, 30, 40]", "Ошибка"]}, {"id": 75, "code": "", "hint": "Если левый индекс пропущен, взятие среза начинается с 0.", "text": "Что означает конструкция `s[:2]` для среза `s := []int{1, 2, 3}`?", "correct": 1, "options": ["Элементы с конца", "Элементы от начала до индекса 2 (не включая)", "Элементы начиная с индекса 2", "Ошибка"]}, {"id": 76, "code": "", "hint": "Если правый индекс пропущен, берется всё до самого конца.", "text": "Что означает конструкция `s[1:]` для среза `s := []int{1, 2, 3}`?", "correct": 1, "options": ["Только первый элемент", "Элементы от индекса 1 до конца среза", "Элементы с шагом 1", "Копию среза"]}, {"id": 77, "code": "m := map[string]int{\\"a\\": 1}", "hint": "Встроенная функция delete() удаляет элемент из карты по указанному ключу.", "text": "Как удалить элемент из карты (map)?", "correct": 0, "options": ["delete(m, \\"a\\")", "m.remove(\\"a\\")", "clear(m)", "m[\\"a\\"] = nil"]}, {"id": 78, "code": "type MyInt int", "hint": "Ключевое слово type объявляет новый именованный тип.", "text": "Какое ключевое слово используется для создания псевдонима типа или определения структуры?", "correct": 2, "options": ["struct", "var", "type", "define"]}, {"id": 79, "code": "msg := \\"Hello\\"\\nfmt.Println(msg[0])", "hint": "Индексация строки возвращает байт (byte) этого символа, поэтому выведется его числовое представление.", "text": "Что выведет код?", "correct": 2, "options": ["H", "Hello", "Числовой код символа (72)", "Ошибка"]}, {"id": 80, "code": "var name string", "hint": "В Go имя переменной пишется перед типом и разделяется обычным пробелом.", "text": "Каким знаком разделяются имя переменной и её тип при стандартном объявлении?", "correct": 2, "options": ["Двоеточием", "Равенством", "Ничем (разделяются пробелом)", "Точкой"]}, {"id": 81, "code": "b := true\\nfmt.Println(!b)", "hint": "Оператор `!` (логическое НЕ) меняет истину на ложь и наоборот.", "text": "Что выведет код?", "correct": 1, "options": ["true", "false", "Ошибка", "nil"]}, {"id": 82, "code": "", "hint": "Сначала пишутся параметры с типами, затем тип возвращаемого значения.", "text": "Как объявить функцию, принимающую два целых числа и возвращающую их сумму?", "correct": 0, "options": ["func add(a int, b int) int", "int add(a, b)", "func add(int a, b)", "void add(a, b int)"]}, {"id": 83, "code": "", "hint": "Если идущие подряд параметры имеют один тип, его можно указать один раз в конце группы.", "text": "Можно ли в Go опустить тип первого параметра функции, если они одинаковые? (Пример: `func add(a, b int)`)", "correct": 1, "options": ["Нет, нельзя", "Да, можно", "Только для типа string", "Только в функциях пакета main"]}, {"id": 84, "code": "func test() (int, int)", "hint": "Функции в Go могут возвращать сколько угодно значений, перечисленных через запятую в круглых скобках.", "text": "Может ли функция в Go возвращать несколько значений?", "correct": 1, "options": ["Нет, только одно", "Да, Go поддерживает множественные возвращаемые значения", "Только если они обернуты в структуру", "Только через указатели"]}, {"id": 85, "code": "val, _ := MyFunction()", "hint": "Пустой идентификатор используется для отбрасывания результатов, которые не пригодятся в коде.", "text": "Что означает пустой идентификатор `_` (нижнее подчеркивание) в Go?", "correct": 1, "options": ["Новая переменная", "Игнорирование (сокрытие) ненужного значения", "Указатель на nil", "Системный флаг"]}, {"id": 86, "code": "", "hint": "Размер массива указывается в квадратных скобках перед типом данных.", "text": "Как объявить массив фиксированной длины из 5 целых чисел?", "correct": 0, "options": ["var arr [5]int", "arr := []int{5}", "var arr int[5]", "make([5]int)"]}, {"id": 87, "code": "", "hint": "Массивы имеют жестко заданную длину, а срезы динамически изменяют свой размер.", "text": "В чем главное отличие массива от среза (slice) в Go?", "correct": 1, "options": ["Массив хранит только строки", "Размер массива фиксирован, а срез может расти", "Срез работает медленнее", "Массивы объявляются через := "]}, {"id": 88, "code": "x := 5\\nx += 3\\nfmt.Println(x)", "hint": "Оператор `+=` прибавляет значение к текущей переменной. 5 + 3 = 8.", "text": "Что выведет код?", "correct": 2, "options": ["5", "3", "8", "Ошибка"]}, {"id": 89, "code": "", "hint": "`defer` гарантирует, что функция выполнится в самом конце, прямо перед выходом из вызывающей функции.", "text": "Какое ключевое слово используется для откладывания вызова функции до момента выхода из текущей функции?", "correct": 0, "options": ["defer", "postpone", "later", "return"]}, {"id": 90, "code": "defer fmt.Print(\\"A\\")\\nfmt.Print(\\"B\\")", "hint": "Печать 'A' отложена, сначала выполнится печать 'B', а затем 'A'.", "text": "Что будет результатом выполнения кода?", "correct": 1, "options": ["AB", "BA", "A", "B"]}, {"id": 91, "code": "m := map[string]int{\\"age\\": 20}", "hint": "Второе возвращаемое значение (обычно называемое ok) указывает на наличие ключа в карте.", "text": "Как правильно проверить, есть ли ключ в карте (map)?", "correct": 1, "options": ["if m.contains(\\"age\\")", "value, ok := m[\\"age\\"]", "if m[\\"age\\"] != nil", "if m[\\"age\\"].exists()"]}, {"id": 92, "code": "for index, value := ...", "hint": "Ключевое слово `range` в цикле for возвращает индекс и значение для каждого элемента.", "text": "С помощью какого ключевого слова можно перебирать элементы среза или карты в цикле?", "correct": 2, "options": ["in", "each", "range", "list"]}, {"id": 93, "code": "nums := []int{10}\\nfor i, v := range nums {\\n    fmt.Print(i, v)\\n}", "hint": "`i` — это индекс (0), а `v` — это значение элемента (10).", "text": "Что выведет код, если перебирать срез через range?", "correct": 1, "options": ["10 10", "0 10", "10 0", "0 0"]}, {"id": 94, "code": "", "hint": "Для импорта нескольких пакетов используются круглые скобки.", "text": "Как импортировать несколько пакетов одновременно?", "correct": 2, "options": ["import \\"fmt\\", \\"math\\"", "import ( \\"fmt\\"; \\"math\\" )", "import (\\n    \\"fmt\\"\\n    \\"math\\"\\n)", "import \\"fmt\\" import \\"math\\""]}, {"id": 95, "code": "fmt.Println(10 == 10 || 5 > 10)", "hint": "Для оператора || (ИЛИ) достаточно, чтобы хотя бы одно условие было верным. 10 == 10 — это true.", "text": "Что выведет выражение?", "correct": 0, "options": ["true", "false", "Ошибка", "10"]}, {"id": 96, "code": "s := fmt.Spln(...)", "hint": "Функция Sprintf форматирует данные по шаблону и возвращает результат в виде строки.", "text": "Какая функция используется для форматирования строки БЕЗ вывода её в консоль?", "correct": 1, "options": ["fmt.Printf()", "fmt.Sprintf()", "fmt.PrintLine()", "fmt.Format()"]}, {"id": 97, "code": "", "hint": "В Go экспортируемость (публичность) определяется заглавной буквой в начале имени.", "text": "Каким регистром должно начинаться имя функции или поля структуры, чтобы они были доступны из других пакетов (публичными)?", "correct": 1, "options": ["Нижним (маленькая буква)", "Верхним (ЗАГЛАВНАЯ буква)", "Символом подчеркивания", "Регистр не имеет значения"]}, {"id": 98, "code": "x := 5\\n{ \\n    x := 10 \\n}\\nfmt.Println(x)", "hint": "Переменная внутри фигурных скобок создала свою область видимости (затенение), внешняя `x` осталась равной 5.", "text": "Что выведет этот код?", "correct": 0, "options": ["5", "10", "Ошибка компиляции", "0"]}, {"id": 99, "code": "", "hint": "Вы можете вкладывать циклы for друг в друга стандартным образом.", "text": "Разрешены ли в Go циклы внутри других циклов (вложенные циклы)?", "correct": 1, "options": ["Нет, запрещены", "Да, без ограничений", "Только до 2 уровней", "Только с использованием меток"]}, {"id": 100, "code": "// Переменная count\\ncount := 0", "hint": "Текст после `//` полностью игнорируется компилятором Go.", "text": "Что делает этот код?", "correct": 1, "options": ["Вызовет ошибку", "Ничего, это комментарий для разработчика и код инициализации", "Выведет текст на экран", "Создаст документацию"]}]}	2026-07-20 15:02:52	2026-07-20 15:02:52
