-- ============================================================
--  GameCode: демонстрационное наполнение для локальной разработки.
--
--  Содержит игры, новости, банк вопросов, теорию чат-бота и уровни
--  Pixelgame. НЕ содержит учётных записей, результатов игроков и
--  журнала админки — там персональные данные и хеши паролей.
--
--  Применять ПОСЛЕ того, как поднялась база со схемой:
--    docker compose exec -T db psql -U gamecode_user -d gamecode < db/seed-demo.sql
--
--  Порядок таблиц задан по внешним ключам: сначала родительские.
-- ============================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);

-- games: 4 строк

-- news: 3 строк

-- pixelgame_levels: 4 строк

-- pixelgame_monster_questions: 1 строк

-- chat_faq: 39 строк

-- chat_faq_keywords: 198 строк

-- questions: 100 строк

-- question_answers: 400 строк

-- последовательности после вставки с явными id
SELECT setval(pg_get_serial_sequence('public.questions','id'),        COALESCE((SELECT MAX(id) FROM public.questions), 1));
SELECT setval(pg_get_serial_sequence('public.question_answers','id'), COALESCE((SELECT MAX(id) FROM public.question_answers), 1));
SELECT setval(pg_get_serial_sequence('public.chat_faq','id'),         COALESCE((SELECT MAX(id) FROM public.chat_faq), 1));
SELECT setval(pg_get_serial_sequence('public.chat_faq_keywords','id'),COALESCE((SELECT MAX(id) FROM public.chat_faq_keywords), 1));
SELECT setval(pg_get_serial_sequence('public.pixelgame_levels','id'), COALESCE((SELECT MAX(id) FROM public.pixelgame_levels), 1));
SELECT setval(pg_get_serial_sequence('public.pixelgame_monster_questions','id'), COALESCE((SELECT MAX(id) FROM public.pixelgame_monster_questions), 1));
